// src/burst-playback.ts
function burstAnimation(names) {
  const combined = names.find((name) => /(?:^|_)all(?:_|$)/i.test(name) && /skill[_-]?cut/i.test(name) && !/(?:^|_)bg(?:_|$)/i.test(name));
  if (combined) return combined;
  for (const preferred of ["skillcut_1", "skill_cut", "skill_01", "skilcut_1"]) {
    if (names.includes(preferred)) return preferred;
  }
  return names.find((name) => /^skill[_-]?cut(?:_|\d|$)/i.test(name) && !/(?:^|_)bg(?:_|$)/i.test(name)) ?? null;
}
function burstPlayback(animations, preferred, overlay, backgrounds) {
  const names = animations.map((a) => a.name);
  const main = preferred && names.includes(preferred) ? preferred : burstAnimation(names);
  if (!main) throw new Error("No burst animation");
  const duration3 = animations.find((a) => a.name === main).duration;
  if (!Number.isFinite(duration3) || duration3 <= 0) throw new Error(`Invalid duration: ${main}`);
  const background = /(?:^|_)all(?:_|$)/i.test(main) ? void 0 : animations.find((a) => a.name === `bg_${main}` || a.name === `${main}_bg`);
  const extraBg = (backgrounds ?? []).filter((name) => name !== background?.name);
  for (const name of extraBg) {
    if (!animations.some((a) => a.name === name)) throw new Error(`Missing background animation: ${name}`);
  }
  const layers = [
    ...background ? [{ role: "background", animation: background.name }] : [],
    ...extraBg.map((name) => ({ role: "background", animation: name })),
    { role: "main", animation: main }
  ];
  for (const name of overlay ?? []) {
    if (!animations.some((a) => a.name === name)) throw new Error(`Missing overlay animation: ${name}`);
    layers.push({ role: "overlay", animation: name });
  }
  if (background && Math.abs(background.duration - duration3) > 0.02) {
    throw new Error(`Background timing needs review: ${main}, ${background.name}`);
  }
  return {
    mode: layers.length > 1 ? "composite" : "single",
    duration: duration3,
    layers
  };
}

// src/burst.ts
var bySkin = new Map(catalog_default.entries.map((entry) => {
  const base = `${catalog_default.assetBase}${entry.directory}/`;
  return [`${entry.resourceId}:${entry.skinIndex}`, {
    id: entry.id,
    format: "spine",
    spineVersion: entry.spineVersion,
    animation: entry.animation,
    animations: entry.animations,
    playback: burstPlayback(entry.animations, entry.animation, entry.extraLayers, entry.bgLayers),
    atlas: base + entry.atlas,
    skeleton: base + entry.skeleton,
    textures: entry.textures.map((name) => ({ name, url: base + name })),
    viewerUrl: `https://nikke-api.pages.dev/burst-viewer?id=${encodeURIComponent(entry.id)}`,
    source: {
      name: "ArtHub",
      url: catalog_default.source,
      revision: catalog_default.commit,
      viewerUrl: `${catalog_default.viewer}?id=${encodeURIComponent(entry.id)}&anim=${encodeURIComponent(entry.animation)}`
    }
  }];
}));
var burstsById = new Map([...bySkin.values()].map((burst) => [burst.id, burst]));
function getBurstCutscene(resourceId, skinIndex = 0) {
  return bySkin.get(`${resourceId}:${skinIndex}`) ?? null;
}
function withBurstCutscenes(nikke) {
  const base = getBurstCutscene(nikke.resourceId);
  return {
    ...nikke,
    burstCutscene: base,
    costumes: nikke.costumes.map((costume) => ({
      ...costume,
      burstCutscene: getBurstCutscene(nikke.resourceId, costume.skinIndex) ?? base
    }))
  };
}
var pickVoice = (voices, skinIndex, re) => {
  const v = voices?.find((x) => (x.costumeIndex ?? 0) === skinIndex && re.test(x.speechId ?? ""));
  return v ? { text: v.text?.ko, audio: v.voice?.ko } : null;
};
var burstVoiceFor = (voices, skinIndex) => ({
  burst: pickVoice(voices, skinIndex, /_Ult_Skill_\d+$/),
  ready: pickVoice(voices, skinIndex, /_Ult_Skill_Ready_\d+$/),
  full: pickVoice(voices, skinIndex, /_FullBurst_\d+$/)
});
function withBurstVoices(nikke, detail) {
  const voices = detail?.voices;
  const base = burstVoiceFor(voices, 0);
  const attach = (b, skinIndex) => {
    if (!b) return null;
    const own2 = burstVoiceFor(voices, skinIndex);
    return { ...b, voice: { burst: own2.burst ?? base.burst, ready: own2.ready ?? base.ready, full: own2.full ?? base.full } };
  };
  return {
    ...nikke,
    burstCutscene: attach(nikke.burstCutscene, 0) ?? null,
    costumes: nikke.costumes.map((co) => ({ ...co, burstCutscene: attach(co.burstCutscene, co.skinIndex) }))
  };
}

